import mime from"mime";import fs from"node:fs";import{pipeline}from"node:stream/promises";import{PublicReturn}from"../../common/public-return.js";import{getGlobalVariables}from"../../action/setup-global-variables.js";export function createRouter(e){const r=getGlobalVariables("rssXmlPath");e.get("/rss.xml",async function(e,o){o.headers({"Content-Type":mime.getType(getGlobalVariables("rssXmlPath"))||""});const t=fs.createReadStream(r);t.on("error",e=>{o.code(404).send(new PublicReturn(404,"没找到文件 rss.xml"))}),await pipeline(t,o.raw)})}